     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div class="shell">
         <header class="hero">
           <div class="eyebrow">Support</div>
           <h1>Contact our support team</h1>
           <p class="lede">Send us your details and we&apos;ll get back to you as soon as possible.</p>
         </header>

         <section class="card" aria-labelledby="contact-form-heading">
           <h2 id="contact-form-heading" class="sr-only" hidden>Contact form</h2>
           <p id="form-status" class="status" aria-live="polite"></p>
           <div id="app"></div>
         </section>
       </div>
     </main>

     <script>
       const state = {
         values: {
           fullName: "",
           email: "",
           phone: "",
         },
         errors: {},
         submitted: false,
         status: "",
         statusTone: "neutral",
       };

       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           required: true,
           autocomplete: "name",
         },
         {
           id: "email-address",
           name: "email",
           label: "Email address",
           type: "email",
           required: true,
           autocomplete: "email",
         },
         {
           id: "phone-number",
           name: "phone",
           label: "Phone number",
           type: "tel",
           required: false,
           autocomplete: "tel",
           helperText: "Format: +1 555 555 5555 or 555-555-5555.",
         },
       ];

       const app = document.getElementById("app");
       const status = document.getElementById("form-status");

       function escapeHtml(value) {
         return String(value)
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function validate(values) {
         const errors = {};
         const name = values.fullName.trim();
         const email = values.email.trim();

         if (!name) {
           errors.fullName = "Please enter your full name.";
         }

         if (!email) {
           errors.email = "Please enter your email address.";
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
           errors.email = "Please enter a valid email address.";
         }

         return errors;
       }

       function fieldMarkup(field, error) {
         const inputId = field.id;
         const helpId = field.helperText ? `${inputId}-help` : "";
         const errorId = `${inputId}-error`;
         const describedBy = [field.helperText ? helpId : "", error ? errorId : ""].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${inputId}">
               ${escapeHtml(field.label)}
               ${field.required ? '<span class="required" aria-hidden="true"> *</span>' : ""}
             </label>
             <input
               id="${inputId}"
               name="${field.name}"
               type="${field.type}"
               value="${escapeHtml(state.values[field.name])}"
               ${field.required ? "required aria-required=\"true\"" : ""}
               autocomplete="${field.autocomplete}"
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
               ${error ? 'aria-invalid="true"' : ""}
             />
             ${field.helperText ? `<div class="help" id="${helpId}">${escapeHtml(field.helperText)}</div>` : ""}
             ${error ? `<div class="error" id="${errorId}">${escapeHtml(error)}</div>` : ""}
           </div>
         `;
       }

       function render() {
         const errorKeys = state.submitted ? validate(state.values) : {};
         state.errors = errorKeys;

         app.innerHTML = `
           <form id="contact-form" novalidate>
             <div class="form-grid">
               ${fields.map((field) => fieldMarkup(field, errorKeys[field.name])).join("")}
               <div class="actions">
                 <button type="submit">Send message</button>
               </div>
             </div>
           </form>
         `;

         status.textContent = state.status;
         status.dataset.tone = state.statusTone;

         const form = document.getElementById("contact-form");
         form.addEventListener("input", handleInput);
         form.addEventListener("submit", handleSubmit);
       }

       function handleInput(event) {
         const { name, value } = event.target;
         if (!name) return;
         state.values[name] = value;
         if (state.submitted) {
           state.errors = validate(state.values);
           state.status = Object.keys(state.errors).length ? "Please fix the highlighted fields." : "";
           state.statusTone = Object.keys(state.errors).length ? "error" : "neutral";
           render();
         }
       }

       function handleSubmit(event) {
         event.preventDefault();
         state.submitted = true;
         state.errors = validate(state.values);

         const hasErrors = Object.keys(state.errors).length > 0;

         if (hasErrors) {
           state.status = "Please fix the highlighted fields.";
           state.statusTone = "error";
           render();
           requestAnimationFrame(() => {
             const firstInvalid = document.querySelector('[aria-invalid="true"]');
             if (firstInvalid) firstInvalid.focus();
           });
           return;
         }

         state.status = "Thanks — your message is ready to send.";
         state.statusTone = "neutral";
         render();
         formReset();
       }

       function formReset() {
         state.values = {
           fullName: "",
           email: "",
           phone: "",
         };
         state.submitted = false;
         setTimeout(() => {
           render();
         }, 0);
       }

       render();
     </script>
   </body>
 </html>

