    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        submitted: false,
        status: "",
        statusTone: "neutral",
      };

      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          autocomplete: "name",
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          helperText: "Format: +1 555 555 5555 or 555-555-5555.",
        },
      ];

      const app = document.getElementById("app");
      const status = document.getElementById("form-status");

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
