           state.statusTone = Object.keys(state.errors).length ? "error" : "neutral";
           render();
         }
       }

       function handleSubmit(event) {
         event.preventDefault();
         state.submitted = true;
         state.errors = validate(state.values);

         const hasErrors = Object.keys(state.errors).length > 0;

         if (hasErrors) {
           state.status = "Please fix the highlighted fields.";
           state.statusTone = "error";
           render();
           requestAnimationFrame(() => {
             const firstInvalid = document.querySelector('[aria-invalid="true"]');
             if (firstInvalid) firstInvalid.focus();
           });
           return;
         }

         state.status = "Thanks — your message is ready to send.";
         state.statusTone = "neutral";
         render();
       }

       render();
     </script>
   </body>
 </html>

